const express = require('express');
const nunjucks = require('nunjucks');
const { init, LDClient } = require('launchdarkly-node-server-sdk');

const app = express();

// Configure nunjucks with autoescape
const env = nunjucks.configure('views', {
  autoescape: true,
  express: app,
  noCache: true
});

// LaunchDarkly client initialization
let ldClient;
async function initLD() {
  ldClient = init(process.env.LD_SDK_KEY || 'sdk-fallback-key');
  await ldClient.waitForInitialization();
  console.log('LaunchDarkly initialized');
}
initLD().catch(err => console.error('LD init failed:', err));

// Middleware to resolve feature flags per request
async function resolveFlags(req, res, next) {
  const user = {
    key: req.headers['x-user-id'] || 'anonymous',
    custom: { tier: req.headers['x-user-tier'] || 'free' }
  };
  try {
    req.flags = {
      enableCustomTemplates: await ldClient.variation('enable-custom-templates', user, false),
      enableBetaRendering: await ldClient.variation('enable-beta-rendering', user, false)
    };
  } catch (e) {
    // On LD failure, all flags default to false
    req.flags = { enableCustomTemplates: false, enableBetaRendering: false };
  }
  next();
}

app.use(resolveFlags);

// Standard safe route - renders pre-defined template
app.get('/dashboard', (req, res) => {
  const username = req.query.name || 'Guest';
  res.render('dashboard.html', { username: username });
});

// Custom template rendering - gated behind feature flag
app.post('/render-custom', express.json(), (req, res) => {
  const { template, context } = req.body;

  // Feature flag gate: custom template rendering
  if (!req.flags.enableCustomTemplates) {
    return res.status(403).json({
      error: 'Custom template rendering is not enabled for your account',
      code: 'FEATURE_DISABLED'
    });
  }

  // WARNING: renders user-supplied template string directly
  try {
    const rendered = nunjucks.renderString(template, context || {});
    res.json({ rendered });
  } catch (err) {
    res.status(400).json({ error: 'Template rendering failed', details: err.message });
  }
});

// Beta rendering endpoint with additional template features
app.post('/beta/render', express.json(), (req, res) => {
  if (!req.flags.enableBetaRendering) {
    return res.status(403).json({ error: 'Beta rendering not available' });
  }

  const { source, data } = req.body;

  // Compile and render with full nunjucks power
  try {
    const tmpl = new nunjucks.Template(source, env);
    const output = tmpl.render(data || {});
    res.json({ output });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', flags: { ldConnected: ldClient && ldClient.initialized() } });
});

app.listen(3000, () => console.log('Server running on :3000'));
